target.css:
:root {
  --ink: #243132;
  --paper: #fffdf7;
  --coral: #d9584f;
  --line: #eadfd2;
  --muted: #697575;
}

.reservation {
  width: 460px;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.reservation-header {
  position: relative;
  padding: 14px 18px;
  background: var(--coral);
  color: var(--paper);
}

.kicker {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.4px;
}

.mark {
  position: absolute;
  top: 8px;
  right: 16px;
  margin: 0;
  font-size: 27px;
}

.reservation-body {
  padding: 20px 18px 18px;
}

.reservation-body h1 {
  margin: 0 0 7px;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.15;
}

.meta {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.reservation-footer {
  padding: 11px 18px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.reservation-footer button {
  margin-left: 18px;
  padding: 6px 10px;
  border: 1px solid var(--coral);
  border-radius: 7px;
  background: var(--paper);
  color: var(--coral);
  font-size: 12px;
  font-weight: 700;
}
